-- existing is touched. The two tables were generated by drizzle-kit and made re-runnable here; the
-- function and triggers at the end are hand-written. Until this runs the code finds the tables
-- missing, keeps the older flow, and reports exact copies as not available.
CREATE TABLE IF NOT EXISTS "evidence_request_decision_submissions" (
	"decision_id" uuid PRIMARY KEY NOT NULL,
	"submission_id" uuid NOT NULL,
	CONSTRAINT "evidence_request_decision_submissions_submission_id_unique" UNIQUE("submission_id")
);
